/** Portable complete native-admission record checks; does not inspect or execute the old producer host. */
final class TomtomRuntimeBundle {
    private TomtomRuntimeBundle() { }
    static void verify(Path root,String producerRoot,String home,Path build,String producerBuild,TomtomRecipe.Mode mode,TomtomRecipe.Request overall,Runnable check)throws IOException {
        TomtomRecipe.nativePath(producerRoot);TomtomRecipe.nativePath(home);var completion=TomtomBundle.json(root.resolve("COMPLETED.json"),65536);var manifest=TomtomBundle.json(root.resolve("manifest.json"),67108864);
        require("COMPLETE_NATIVE_TOMTOM_RUNTIME_HEALTH_ONLY".equals(completion.get("status"))&&Boolean.FALSE.equals(completion.get("user_analysis_admitted"))&&NextflowFiles.fingerprint(completion.get("manifest"),67108864).equals(NextflowFiles.pin(root.resolve("manifest.json"),67108864,check)),"Captured native Tomtom runtime completion differs");
        require("NATIVE_RUNTIME_HEALTH_ONLY".equals(manifest.get("status"))&&TomtomRecipe.PROFILE.equals(manifest.get("profile"))&&mode.name().equals(manifest.get("output_mode"))&&home.equals(manifest.get("home"))&&Boolean.FALSE.equals(manifest.get("user_analysis_admitted")),"Captured native runtime profile/home/capability/status differs");
        TomtomBundle.verifyInventory(root,manifest.get("files"),overall,Set.of("manifest.json","COMPLETED.json"),check);
        var request=TomtomBundle.json(root.resolve("metadata/request.json"),2097152);NextflowFiles.keys(request,"profile","output_mode","home","build_evidence","installation_performed","user_analysis_admitted");require(TomtomRecipe.PROFILE.equals(request.get("profile"))&&mode.name().equals(request.get("output_mode"))&&home.equals(request.get("home"))&&producerBuild.equals(request.get("build_evidence"))&&Boolean.FALSE.equals(request.get("installation_performed"))&&Boolean.FALSE.equals(request.get("user_analysis_admitted")),"Captured native admission request differs");
        var source=MemeBuildEvidence.read(build,new MemeRuntimeFiles.Limits(67108864,268435456,10000),check);require(source.prefix().equals(home),"Captured build evidence and original compiled runtime prefix differ");var host=TomtomBundle.json(root.resolve("metadata/host.json"),67108864);
        require(home.equals(host.get("home"))&&TomtomRecipe.PROFILE.equals(host.get("profile"))&&mode.name().equals(host.get("output_mode"))&&source.completion().equals(NextflowFiles.fingerprint(host.get("build_completion"),2097152)),"Captured native host/source identity differs");
        var platform=NextflowFiles.object(host.get("platform"));require("Linux".equals(platform.get("os"))&&"x86_64".equals(platform.get("architecture")),"Captured native runtime producer is not supported Linux x86_64");var environment=Map.of("PATH",home+"/bin:"+home+"/libexec/meme-5.5.9:/usr/bin:/bin","LANG","C","LC_ALL","C","TZ","UTC");require(environment.equals(NextflowFiles.object(host.get("environment_without_owned_HOME_TMPDIR"))),"Captured native Tomtom environment differs");
        var snapshot=NextflowFiles.object(host.get("complete_host_files"));var trees=NextflowFiles.object(snapshot.get("trees"));var payload=NextflowFiles.object(trees.get(home));var actualPayload=new java.util.TreeMap<String,NextflowFiles.Pin>();
        for(var e:payload.entrySet()){var node=NextflowFiles.object(e.getValue());if("REGULAR".equals(node.get("kind")))actualPayload.put((String)e.getKey(),NextflowFiles.fingerprint(node.get("file"),268435456));else require("DIRECTORY".equals(node.get("kind")),"Unsupported original native payload node in host record");}require(actualPayload.equals(source.installed()),"Complete original payload hashes differ between build and native host records");
        require(NextflowFiles.object(host.get("ELF_images")).containsKey(home+"/bin/tomtom")&&!NextflowFiles.object(host.get("ELF_bindings")).isEmpty(),"Captured native Tomtom ELF closure is missing");
        if(mode==TomtomRecipe.Mode.TEXT)require(host.get("Perl_report_capability")==null,"Text-only captured runtime acquired an unrequested Perl report capability");else{var perl=NextflowFiles.object(host.get("Perl_report_capability"));require(!NextflowFiles.object(perl.get("loaded_modules")).isEmpty()&&!NextflowFiles.list(perl.get("loaded_native_images")).isEmpty(),"Captured full-report Perl/native XML capability is incomplete");}
        var health=TomtomBundle.json(root.resolve("metadata/health.json"),2097152);require("PASSED_FRESH_ORIGINAL_FIXED_REFERENCE_HEALTH".equals(health.get("status"))&&Boolean.FALSE.equals(health.get("user_analysis_admitted"))&&NextflowFiles.list(health.get("fits")).size()==2,"Captured native complete health family differs");
        var lock=MemeRuntimeFiles.lock();var references=NextflowFiles.object(SimpleJson.parse(NextflowFiles.utf8(MemeRuntimeFiles.resource(MemeRuntimeFiles.RESOURCE+"health-reference.json",NextflowFiles.fingerprint(lock.get("health_reference"),2097152)))));int number=0;
        for(Object value:NextflowFiles.list(references.get("cases"))){var spec=NextflowFiles.object(value);String label=NextflowFiles.text(spec.get("label"));var inputs=TomtomCapturedInputs.read(root.resolve("health/"+label+"/prepared"),producerRoot+"/health/"+label+"/prepared",check);var recipe=inputs.request();require(recipe.mode()==mode&&recipe.distance().equals(spec.get("distance"))&&recipe.reverseComplement()==(Boolean)spec.get("reverse_complement")&&recipe.threshold().compareTo(java.math.BigDecimal.ONE)==0&&recipe.thresholdKind()==TomtomRecipe.Threshold.QVALUE&&recipe.pseudocount().compareTo(new java.math.BigDecimal("0.1"))==0&&recipe.minimumOverlap()==1&&!recipe.internal()&&recipe.completeScores()&&recipe.background()==TomtomRecipe.Background.QUERY,"Captured native health scientific recipe differs from fixed reference");
            var motif=NextflowFiles.fingerprint(lock.get("health_motifs"),2097152);for(var file:inputs.files())require(file.pin().equals(motif),"Captured native health raw model identity differs");String process=producerRoot+"/probes/health-"+label;String output=mode==TomtomRecipe.Mode.TEXT?null:process+"/result";var command=recipe.arguments(home+"/bin/tomtom",inputs.query(),inputs.targets(),inputs.backgroundFile(),output);
            var ledger=TomtomBundle.json(root.resolve("probes/health-"+label+"/process.json"),16777216);var accounted=NextflowFiles.strings(ledger.get("accounted_roots"));var expectedAccounting=new java.util.HashSet<String>(List.of(producerRoot+"/metadata",producerRoot+"/inputs",producerRoot+"/health",producerRoot+"/probes/version"));int images=NextflowFiles.object(host.get("ELF_images")).size();require(NextflowFiles.object(host.get("ELF_bindings")).size()==images,"Captured native image/binding populations differ");for(int i=0;i<images;i++)expectedAccounting.add(producerRoot+"/probes/libraries-"+i);if(mode==TomtomRecipe.Mode.FULL_REPORT)expectedAccounting.addAll(List.of(producerRoot+"/probes/perl-imports",producerRoot+"/probes/perl-imports-recheck"));if(number>0)expectedAccounting.add(producerRoot+"/probes/health-ed-forward");require(accounted.size()==expectedAccounting.size()&&new java.util.HashSet<>(accounted).equals(expectedAccounting),"Complete native health preparation/probe accounting family differs");TomtomProcessReceipt.verify(root.resolve("probes/health-"+label),command,TomtomRuntime.Limits.defaults().process(),accounted,check);var result=TomtomOutput.read(root.resolve("probes/health-"+label),inputs,command,check);require(result.matches().size()==result.pairs().size()&&result.pairs().size()==9,"Captured native health comparison population differs");
            Path table=root.resolve("probes/health-"+label+(mode==TomtomRecipe.Mode.TEXT?"/process.stdout":"/result/tomtom.tsv"));var rows=new ArrayList<List<String>>();for(String line:NextflowFiles.utf8(NextflowFiles.bytes(table,8388608)).split("\n"))if(!line.isBlank()&&!line.startsWith("#")&&!line.startsWith("Query_ID\t"))rows.add(List.of(line.split("\t",-1)));var expectedRows=new ArrayList<List<String>>();for(Object row:NextflowFiles.list(spec.get("rows")))expectedRows.add(NextflowFiles.strings(row));require(rows.equals(expectedRows),"Copied native health rows differ from all ten original reference columns");
            var recorded=NextflowFiles.object(NextflowFiles.list(health.get("fits")).get(number++));require(label.equals(recorded.get("label"))&&mode.name().equals(recorded.get("output_mode"))&&Boolean.TRUE.equals(recorded.get("all_ten_columns_exact_original_match"))&&NextflowFiles.integer(recorded.get("complete_declared_pairs"),9,9)==9&&NextflowFiles.integer(recorded.get("complete_reported_rows"),9,9)==9&&NextflowFiles.list(recorded.get("owned_live_after_cleanup")).isEmpty()&&Boolean.FALSE.equals(recorded.get("user_analysis_admitted"))&&NextflowFiles.fingerprint(recorded.get("table"),8388608).equals(NextflowFiles.pin(table,8388608,check)),"Copied native health receipt differs from complete captured evidence");
        }
        source.verify(check);
    }
    private static void require(boolean value,String message)throws IOException {MemeRuntimeFiles.require(value,message);}
}
